// Noto Sans KR 600, ASCII and modern Hangul subset. SIL OFL: label-font-LICENSE.txt.
const encoded = "";
let cached: Promise<Uint8Array> | undefined;
export function labelFont(): Promise<Uint8Array> {
  return cached ??= new Response(new Blob([Uint8Array.from(atob(encoded), c => c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream("gzip"))).arrayBuffer().then(b => new Uint8Array(b));
}
